#!/usr/bin/env python3
"""
Patch 05: generic, schema-driven cards.

Run from the repository root. Stages every change in memory, checks every
anchor and the current App.jsx fingerprint, and writes nothing unless all of
it matches. Safe to re-run: anything already in place is skipped.

  new:     14 files (src/useCase.js, src/ui/*, src/cards/*)
  replace: frontend/src/App.jsx (only if it is the expected current version)
  edit:    api.js, AskConsole.jsx, TimeSliderMap.jsx (chrome only), CHANGELOG.md
  delete:  10 superseded panels
"""
import hashlib, os, sys

def abort(msg):
    sys.exit(f"ABORT: {msg}. No files were written.")

if not (os.path.isfile("frontend/src/App.jsx") and os.path.isdir("slicktrace_core")):
    abort("run this from the slick-trace repository root")

NEW = {'frontend/src/useCase.js': "import { useEffect, useState } from 'react';\nimport { api } from './api';\n\n/**\n * Everything the cards need for one incident.\n *\n * case    the Case contract (/case): one validated object assembled from the\n *         committed artifacts.\n * report  /report, for the status counts and checksum list the contract\n *         does not carry.\n * tracks  /tracks, for the replay map.\n *\n * Responses for a case that is no longer selected are dropped, so switching\n * quickly can never leave one case's evidence beside another's.\n */\nconst EMPTY = { case: null, report: null, tracks: null, error: null };\n\nexport function useCase(incidentId) {\n  const [state, setState] = useState(EMPTY);\n\n  useEffect(() => {\n    let live = true;\n    setState(EMPTY);\n    const put = (k) => (v) => { if (live) setState((s) => ({ ...s, [k]: v })); };\n    api.case(incidentId).then(put('case'))\n      .catch((e) => put('error')(String(e.message ?? e)));\n    api.report(incidentId).then(put('report')).catch(() => {});\n    api.tracks(incidentId).then(put('tracks')).catch(() => {});\n    return () => { live = false; };\n  }, [incidentId]);\n\n  return state;\n}\n", 'frontend/src/ui/primitives.jsx': '/**\n * Generic building blocks every case card is composed from.\n *\n * Card: a section in the shell\'s hairline style, with title, badge, an\n * always-visible caption and a footnote. Stat: a value with its plain\n * caption underneath. BarList: ranked horizontal bars for either direction\n * of "better", with an optional gate marker. None of these compute anything\n * beyond scaling a bar to its row.\n */\n\nimport \'./ui.css\';\n\nexport function Card({ title, badge, caption, footnote, className = \'\', children }) {\n  return (\n    <section className={`panel card ${className}`.trim()}>\n      <div className="panel-head">\n        <h2>{title}</h2>\n        {badge}\n      </div>\n      {caption && <p className="card-caption">{caption}</p>}\n      {children}\n      {footnote && <p className="card-foot">{footnote}</p>}\n    </section>\n  );\n}\n\nconst TONE = { neutral: \'tag\', accent: \'tag tag-teal\', warning: \'tag tag-amber\' };\n\nexport function Badge({ tone = \'neutral\', children }) {\n  return <span className={TONE[tone] ?? TONE.neutral}>{children}</span>;\n}\n\nexport function Stat({ label, value, caption, mono = false, text = false }) {\n  return (\n    <div className="stat">\n      <div className="stat-label">{label}</div>\n      <div className={`stat-value${mono ? \' is-mono\' : \'\'}${text ? \' is-text\' : \'\'}`}>{value}</div>\n      {caption && <div className="stat-caption">{caption}</div>}\n    </div>\n  );\n}\n\nexport function StatGrid({ cols = 3, children }) {\n  return <div className="stat-grid" style={{ \'--cols\': cols }}>{children}</div>;\n}\n\nexport function EmptyState({ children }) {\n  return <p className="card-empty">{children}</p>;\n}\n\n/**\n * rows: [{ key, value, sub }]. max defaults to the largest value. marker draws\n * a tick at a fixed value (a gate) in every row. highlightKey marks one row.\n */\nexport function BarList({ rows, max, marker, format, highlightKey, label }) {\n  const scale = max ?? Math.max(...rows.map((r) => r.value), 1e-9);\n  const pct = (v) => `${Math.max(0, Math.min(1, v / scale)) * 100}%`;\n  return (\n    <div className="barlist" role="table" aria-label={label}>\n      {rows.map((r, i) => (\n        <div role="row" key={r.key} style={{ \'--i\': i }}\n             className={`bar-row${r.key === highlightKey ? \' is-top\' : \'\'}`}>\n          <span role="cell" className="bar-key">{r.key}</span>\n          <span role="cell" className="bar-track" aria-hidden="true">\n            <span className="bar-fill" style={{ width: pct(r.value) }} />\n            {marker && <span className="bar-marker" style={{ left: pct(marker.value) }} />}\n          </span>\n          <span role="cell" className="bar-value">\n            {format(r.value)}\n            {r.sub && <span className="bar-sub">{r.sub}</span>}\n          </span>\n        </div>\n      ))}\n      {marker && (\n        <div className="bar-legend" aria-hidden="true">\n          <span className="bar-legend-tick" /> {marker.label}\n        </div>\n      )}\n    </div>\n  );\n}\n\nexport function CaptionList({ items }) {\n  return (\n    <dl className="caption-list">\n      {items.map(([term, text]) => (\n        <div key={term}>\n          <dt>{term}</dt>\n          <dd>{text}</dd>\n        </div>\n      ))}\n    </dl>\n  );\n}\n', 'frontend/src/ui/glossary.js': "/**\n * Plain-language captions, shown under every non-obvious number by default.\n *\n * One sentence each, written for someone who has not read the method. They\n * describe what a value means, never what it proves: a caption that implied\n * guilt, certainty or a calibrated probability would be wrong.\n */\n\nexport const CAPTIONS = {\n  // forward replay\n  meanIou: 'How much the replayed slick overlaps the observed one, from 0 (none) to 1 (exact).',\n  fitGate: 'Below this overlap no vessel is named, rather than naming the least-bad fit.',\n  variants: 'In how many of the tested current and diffusion settings this vessel fit best.',\n  lossGap: 'How far ahead the leader’s fit is; under 0.05 the top two are effectively tied.',\n  replayMethod: 'Physics-based particle tracking: each release is drifted forward under the same set '\n    + 'of forcing perturbations for every vessel.',\n  firstEntry: 'Earliest hour before the image at which the vessel was inside the traced-back origin area.',\n\n  // proximity baseline\n  distance: 'Straight-line gap to the slick at image time; 0.01° is about 1.1 km.',\n  baselineMethod: 'Picks whichever vessel was nearest the slick when the image was taken, from every '\n    + 'vessel in the scene. It is the shortcut forward replay is measured against.',\n\n  // historical filtering\n  candidate: 'Inside the traced-back origin area at some tested hour, so it goes on to replay.',\n  excluded: 'Tracked at every tested hour and never inside the origin area.',\n  unassessed: 'Track data missing for part of the window, so the vessel is not cleared.',\n\n  // scene and detection\n  area: 'Sea surface covered by the detected outline.',\n  perimeter: 'Length of the outline’s edge.',\n  majorAxis: 'Extent of the slick along its long axis.',\n  minorAxis: 'Extent of the slick across its long axis.',\n  elongation: 'Length divided by width; 1 is round, higher is streak-like.',\n  bearing: 'Direction of the long axis, clockwise from north.',\n  truthIou: 'Agreement between this outline and the generator’s own slick mask, from 0 to 1. '\n    + 'Available only because the case is synthetic.',\n  darkness: 'Dark radar patches can also be calm water or natural films; darkness alone is not proof of oil.',\n  pixelSpacing: 'Ground distance covered by one image pixel.',\n\n  // replay map\n  replay: 'Drag the slider to step back hour by hour. The shaded area is where the slick could have '\n    + 'drifted from by then, widening because release time and spreading are unknown.',\n\n  // fragility\n  leadHeld: 'Share of the tested assumption changes that kept the same leader.',\n  magnitude: 'Size of the smallest tested change that flips the leader; 1.0 means one setting pushed '\n    + 'to the edge of its plausible range.',\n  sweep: 'Pick one setting and a tested value to see who leads under it. Only computed runs are shown.',\n  lossMargin: 'How far the leader’s fit is ahead of the next vessel under this setting.',\n\n  // forecast\n  horizon: 'Hours after the image.',\n  envelopeArea: 'Area of image cells holding at least one modelled particle at that hour.',\n  shoreline: 'Share of modelled particles on the coast side of the shoreline; not a damage estimate.',\n  exposure: 'Share of modelled particles inside the named area at that hour.',\n\n  // next observation\n  recommended: 'The tested future time at which one more image would best tell the top two explanations apart.',\n  disagreement: 'How differently the top two explanations predict the slick will look then; higher is more telling.',\n  overlapIou: 'How much their predicted footprints overlap then, from 0 (none) to 1 (identical).',\n\n  // coverage\n  hiddenRecovery: 'Of vessels in the scene whose AIS was hidden in the test, the share still flagged as '\n    + 'unidentified contacts; ones the radar missed count as not recovered. Higher is better.',\n  falseAlert: 'Of contacts flagged unidentified, the share that were in fact broadcasting. Lower is better.',\n  mistakenPromotion: 'Share of test runs in which hiding the leading vessel’s AIS lets an unrelated contact '\n    + 'become the first thing an analyst would look at. Lower is better.',\n  lossRanking: 'Leadership is decided by the overall fit loss, not overlap alone, so a new leader can show a lower IoU.',\n  gateRadius: 'How close a radar contact and an AIS position must be to count as the same vessel.',\n  notMeasured: '“Not measured” means the test had nothing to count, not a rate of zero.',\n\n  // provenance\n  seed: 'The number that regenerates this synthetic case exactly.',\n  checksums: 'File fingerprints showing the artifacts were not altered, not that the observation is true.',\n\n  // ask\n  ask: 'Answers come from fixed question templates over this case’s files, each with its source cited. '\n    + 'Questions outside those templates are declined.',\n};\n", 'frontend/src/ui/ui.css': '/* Generic card primitives, drawn with the design-system tokens. */\n\n.card-caption {\n  margin: -6px 0 var(--space-4);\n  max-width: 72ch;\n  font-size: var(--font-size-sm);\n  line-height: 1.45;\n  color: var(--label-2);\n}\n\n.card-foot {\n  margin: var(--space-4) 0 0;\n  max-width: 80ch;\n  font-size: var(--font-size-xs);\n  line-height: 1.45;\n  color: var(--label-2);\n}\n\n.card-empty {\n  margin: 0;\n  font-size: var(--font-size-sm);\n  color: var(--label-2);\n}\n\n/* --------------------------------------------------------------- stats */\n\n.stat-grid {\n  display: grid;\n  grid-template-columns: repeat(var(--cols, 3), minmax(0, 1fr));\n  gap: var(--space-4) var(--space-6);\n}\n\n.stat {\n  min-width: 0;\n}\n\n.stat-label {\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-semibold);\n  letter-spacing: 0.01em;\n  color: var(--label-2);\n}\n\n.stat-value {\n  margin-top: 2px;\n  font-size: var(--font-size-lg);\n  font-weight: var(--font-weight-medium);\n  line-height: 1.25;\n  letter-spacing: -0.01em;\n  color: var(--label-1);\n  font-variant-numeric: tabular-nums;\n  overflow-wrap: anywhere;\n}\n\n.stat-value.is-mono {\n  font-family: var(--font-mono);\n  font-size: var(--font-size-md);\n  letter-spacing: 0;\n}\n\n.stat-value.is-text {\n  font-size: var(--font-size-sm);\n  font-weight: var(--font-weight-normal);\n  line-height: 1.4;\n  letter-spacing: 0;\n}\n\n.stat-caption {\n  margin-top: 3px;\n  font-size: var(--font-size-xs);\n  line-height: 1.4;\n  color: var(--label-2);\n}\n\n/* ----------------------------------------------------------------- bars */\n\n.barlist {\n  display: grid;\n  gap: 6px;\n}\n\n.bar-row {\n  display: grid;\n  grid-template-columns: 92px minmax(0, 1fr) 118px;\n  align-items: center;\n  gap: var(--space-3);\n  padding: 3px 6px;\n  margin: 0 -6px;\n  border-radius: var(--radius-sm);\n  transition: background-color var(--dur-fast) ease;\n}\n\n.bar-row:hover {\n  background: var(--fill-hover);\n}\n\n.bar-key {\n  font-family: var(--font-mono);\n  font-size: var(--font-size-sm);\n  color: var(--label-strong);\n  font-variant-numeric: tabular-nums;\n}\n\n.bar-row.is-top .bar-key {\n  color: var(--label-1);\n  font-weight: var(--font-weight-semibold);\n}\n\n.bar-track {\n  position: relative;\n  height: 8px;\n  border-radius: 4px;\n  background: var(--surface-sunken);\n}\n\n.bar-fill {\n  position: absolute;\n  inset: 0 auto 0 0;\n  border-radius: 4px;\n  background: var(--label-3);\n  transform-origin: left center;\n  animation: bar-grow var(--dur-slow) var(--ease-spring) both;\n  animation-delay: calc(var(--i, 0) * 35ms);\n}\n\n.bar-row.is-top .bar-fill {\n  background: var(--accent);\n}\n\n.bar-marker {\n  position: absolute;\n  top: -3px;\n  bottom: -3px;\n  width: 1.5px;\n  margin-left: -0.75px;\n  border-radius: 1px;\n  background: var(--label-1);\n  opacity: 0.55;\n}\n\n.bar-value {\n  font-family: var(--font-mono);\n  font-size: var(--font-size-sm);\n  color: var(--label-1);\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n}\n\n.bar-sub {\n  margin-left: 8px;\n  color: var(--label-2);\n}\n\n.bar-legend {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  margin-top: 2px;\n  padding-left: calc(92px + var(--space-3));\n  font-size: var(--font-size-xs);\n  color: var(--label-2);\n}\n\n.bar-legend-tick {\n  display: inline-block;\n  width: 1.5px;\n  height: 11px;\n  background: var(--label-1);\n  opacity: 0.55;\n}\n\n@keyframes bar-grow {\n  from { transform: scaleX(0); }\n  to   { transform: scaleX(1); }\n}\n\n/* -------------------------------------------------------- caption lists */\n\n.caption-list {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: var(--space-2) var(--space-6);\n  margin: var(--space-4) 0 0;\n}\n\n.caption-list dt {\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-semibold);\n  color: var(--label-strong);\n}\n\n.caption-list dd {\n  margin: 1px 0 0;\n  font-size: var(--font-size-xs);\n  line-height: 1.4;\n  color: var(--label-2);\n}\n\n/* --------------------------------------------------------------- tables */\n\n.ui-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: var(--font-size-sm);\n}\n\n.ui-table th,\n.ui-table td {\n  padding: 9px 12px 9px 0;\n  text-align: left;\n  vertical-align: top;\n  border-bottom: 1px solid var(--separator);\n}\n\n.ui-table thead th {\n  padding-top: 0;\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-semibold);\n  color: var(--label-2);\n}\n\n.ui-table tbody th {\n  font-weight: var(--font-weight-medium);\n  color: var(--label-1);\n  white-space: nowrap;\n}\n\n.ui-table td {\n  color: var(--label-1);\n  font-variant-numeric: tabular-nums;\n}\n\n.ui-table .muted {\n  color: var(--label-2);\n}\n\n.ui-table .sub {\n  display: block;\n  margin-top: 2px;\n  font-size: var(--font-size-xs);\n  color: var(--label-2);\n}\n\n.ui-list {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.ui-list li + li {\n  margin-top: 3px;\n}\n\n/* --------------------------------------------------------------- finding */\n\n.finding {\n  border-top: 0;\n  margin-top: var(--space-6);\n  padding: var(--space-5) var(--space-6) var(--space-5);\n  border-radius: var(--radius-xl);\n  background: var(--surface-sunken);\n  box-shadow: inset 0 0 0 0.5px var(--separator);\n}\n\n.finder-features .finding > .panel-head {\n  position: static;\n  margin: 0 0 var(--space-2);\n  padding: 0;\n  background: none;\n  -webkit-backdrop-filter: none;\n  backdrop-filter: none;\n}\n\n.finding-line {\n  margin: 0 0 var(--space-4);\n  font-size: var(--font-size-md);\n  line-height: 1.4;\n  color: var(--label-1);\n}\n\n.finding-compare {\n  display: grid;\n  grid-template-columns: 1fr auto 1fr;\n  gap: var(--space-4);\n  align-items: start;\n}\n\n.finding-side-label {\n  margin-bottom: 4px;\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-semibold);\n  color: var(--label-2);\n}\n\n.finding-side.is-muted .stat-value {\n  color: var(--label-2);\n}\n\n.finding-arrow {\n  align-self: center;\n  color: var(--label-3);\n  font-size: 18px;\n}\n\n.finding-note {\n  margin: var(--space-4) 0 0;\n  padding-top: var(--space-3);\n  border-top: 1px solid var(--separator);\n  font-size: var(--font-size-xs);\n  line-height: 1.45;\n  color: var(--label-2);\n}\n\n/* ------------------------------------------------------------ controls */\n\n.ui-select {\n  height: 26px;\n  padding: 0 26px 0 10px;\n  border: 0;\n  border-radius: 7px;\n  background: var(--control-bg);\n  box-shadow: var(--shadow-control);\n  color: var(--label-1);\n  font-size: var(--font-size-sm);\n}\n\n.ui-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--space-2) var(--space-3);\n}\n\n.flip-box {\n  margin-top: var(--space-4);\n  padding: var(--space-3) var(--space-4);\n  border-radius: var(--radius-lg);\n  background: var(--status-orange-soft);\n}\n\n.flip-box .stat-value {\n  font-size: var(--font-size-md);\n}\n\n.chip-steps {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.chip {\n  display: inline-flex;\n  align-items: center;\n  height: 24px;\n  padding: 0 10px;\n  border: 0;\n  border-radius: 7px;\n  background: var(--surface-sunken);\n  color: var(--label-1);\n  font-family: var(--font-mono);\n  font-size: var(--font-size-xs);\n  font-variant-numeric: tabular-nums;\n  cursor: default;\n  transition: transform var(--dur-base) var(--ease-spring), background-color var(--dur-fast) ease;\n}\n\nbutton.chip:hover {\n  background: var(--fill-pressed);\n}\n\nbutton.chip:active {\n  transform: scale(0.95);\n  transition-duration: var(--dur-fast);\n}\n\n.chip.is-active {\n  background: var(--accent);\n  color: var(--on-accent);\n}\n\n.chip.is-flag {\n  box-shadow: inset 0 0 0 1px var(--status-orange);\n}\n\n@media (max-width: 900px) {\n  .stat-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .finding-compare { grid-template-columns: 1fr; }\n  .finding-arrow { display: none; }\n  .bar-row { grid-template-columns: 84px minmax(0, 1fr) 96px; }\n}\n', 'frontend/src/cards/CaseFindingCard.jsx': 'import { Badge, Card, Stat } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * The finding, stated before the evidence.\n *\n * Wording stays neutral: the proximity pick is "not supported by forward\n * replay", never "wrong" or struck through, because the interface has no\n * ground truth to call anything wrong. On an abstention it says so plainly.\n */\nexport default function CaseFindingCard({ attribution, baseline, vessels }) {\n  if (!attribution || !baseline) return null;\n\n  const nearest = baseline.ranking[0];\n  const top = attribution.ranking[0];\n  const runnerUp = attribution.ranking[1];\n  const unknown = attribution.unknown_source;\n  const nCandidates = attribution.candidates_considered.length;\n  const disc = attribution.discrimination;\n  const topVessel = vessels?.find((v) => v.vessel_key === top?.vessel_key);\n  const differs = !unknown && nearest && top && nearest.vessel_key !== top.vessel_key;\n\n  const badge = unknown\n    ? <Badge tone="warning">Unknown source</Badge>\n    : <Badge tone="accent">{differs ? \'Nearest vessel not supported\' : \'Candidate named\'}</Badge>;\n\n  return (\n    <Card title="Case Finding" badge={badge} className="finding">\n      <p className="finding-line">\n        {unknown\n          ? `No vessel is named. Forward replay tested ${nCandidates} candidate vessel${nCandidates === 1 ? \'\' : \'s\'}, and none fit the observed slick well enough to reach the gate.`\n          : differs\n            ? \'The nearest vessel is not supported by forward replay; the best physical fit is another vessel.\'\n            : \'The nearest vessel is also the best physical fit under forward replay.\'}\n      </p>\n\n      <div className="finding-compare">\n        <div className={`finding-side${differs || unknown ? \' is-muted\' : \'\'}`}>\n          <div className="finding-side-label">Proximity baseline picks</div>\n          <Stat mono label="Nearest at image time" value={nearest?.vessel_key}\n                caption={`${nearest?.distance_deg.toFixed(3)}° from the slick. ${C.distance}`} />\n        </div>\n        <span className="finding-arrow" aria-hidden="true">→</span>\n        <div className="finding-side">\n          <div className="finding-side-label">Forward replay</div>\n          {unknown ? (\n            <Stat label="Best fit, not named" value={`mean IoU ${top?.mean_iou.toFixed(3)}`}\n                  caption={`Gate ${attribution.abstention_iou_gate}. ${C.fitGate}`} />\n          ) : (\n            <Stat mono label="Best physical fit" value={top?.vessel_key}\n                  caption={`Mean IoU ${top?.mean_iou.toFixed(3)}${runnerUp ? ` against ${runnerUp.mean_iou.toFixed(3)} for the runner-up` : \'\'}. ${C.meanIou}`} />\n          )}\n        </div>\n      </div>\n\n      {!unknown && topVessel?.first_entry_hours_before != null && (\n        <p className="card-caption" style={{ marginTop: \'var(--space-3)\', marginBottom: 0 }}>\n          Inside the origin area {topVessel.first_entry_hours_before} h before the image. {C.firstEntry}\n        </p>\n      )}\n      {!unknown && disc?.discriminated === false && (\n        <p className="card-caption" style={{ marginTop: \'var(--space-2)\', marginBottom: 0 }}>\n          The top two are not separated: loss gap {disc.loss_gap}, under {disc.tolerance}. {C.lossGap}\n        </p>\n      )}\n\n      <p className="finding-note">\n        {unknown\n          ? \'A source vessel may have left the scene before the image. Declining to name one is the correct output here.\'\n          : \'A ranking reflects physical consistency under tested assumptions: an investigative lead, not proof of responsibility.\'}\n      </p>\n    </Card>\n  );\n}\n', 'frontend/src/cards/CandidateRankingCard.jsx': 'import { Badge, BarList, CaptionList, Card, EmptyState } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * One ranked list, parameterized by kind:\n *   "baseline"  proximity to the slick at image time, every vessel (lower = nearer)\n *   "replay"    forward-replay mean IoU, candidates only (higher = better fit),\n *               with the fit gate drawn on every bar\n *\n * The badges say how the two relate, never "right" or "wrong": the interface\n * has no ground truth to judge either.\n */\nexport default function CandidateRankingCard({ kind, attribution, baseline }) {\n  if (kind === \'baseline\') {\n    if (!baseline) return null;\n    const relation = !attribution ? null\n      : attribution.unknown_source ? \'forward replay names no one\'\n        : baseline.top_candidate_id === attribution.top_candidate_id\n          ? \'agrees with forward replay\' : \'disagrees with forward replay\';\n    return (\n      <Card title="Proximity Baseline"\n            badge={relation && <Badge>{relation}</Badge>}\n            caption={C.baselineMethod}>\n        <BarList label="Distance from each vessel to the slick at image time"\n                 rows={baseline.ranking.map((r) => ({ key: r.vessel_key, value: r.distance_deg }))}\n                 format={(v) => `${v.toFixed(3)}°`} highlightKey={baseline.top_candidate_id} />\n        <p className="card-foot">{C.distance} Shorter bar is nearer; the nearest is highlighted.</p>\n      </Card>\n    );\n  }\n\n  if (!attribution) return null;\n  const unknown = attribution.unknown_source;\n  return (\n    <Card title="Forward-Replay Ranking"\n          badge={<Badge tone={unknown ? \'warning\' : \'accent\'}>{unknown ? \'abstained\' : \'named\'}</Badge>}\n          caption={C.replayMethod}>\n      {attribution.ranking.length === 0 ? (\n        <EmptyState>No candidate survived historical filtering, so none was replayed.</EmptyState>\n      ) : (\n        <BarList label="Mean IoU of each candidate\'s best replayed release"\n                 rows={attribution.ranking.map((r) => ({\n                   key: r.vessel_key, value: r.mean_iou,\n                   sub: `${r.ensemble_win_count}/${r.n_ensemble}`,\n                 }))}\n                 max={1} format={(v) => v.toFixed(3)}\n                 marker={{ value: attribution.abstention_iou_gate, label: `fit gate ${attribution.abstention_iou_gate}` }}\n                 highlightKey={unknown ? null : attribution.top_candidate_id} />\n      )}\n      <CaptionList items={[\n        [\'Bar: mean IoU\', C.meanIou],\n        [`Tick: fit gate ${attribution.abstention_iou_gate}`, C.fitGate],\n        [`n/${attribution.n_ensemble_variants}`, C.variants],\n      ]} />\n    </Card>\n  );\n}\n', 'frontend/src/cards/ObservedSceneCard.jsx': 'import { Badge, Card, Stat, StatGrid } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * Values are shown at the precision the detection artifact rounds them to.\n *\n * The observed scene with the detector\'s outline drawn on it, and the\n * outline\'s measurements. The raw image alone proves nothing; the outline is\n * what the classical baseline detector retained.\n */\nexport default function ObservedSceneCard({ meta, slick, sceneUrl, nVessels }) {\n  if (!meta) return null;\n  const synthetic = meta.provenance?.status === \'synthetic\';\n  const b = meta.bbox;\n  const g = slick?.geometry;\n  const pts = (slick?.polygon ?? []).map(([lon, lat]) => {\n    const x = ((lon - b.min_lon) / (b.max_lon - b.min_lon)) * 100;\n    const y = ((b.max_lat - lat) / (b.max_lat - b.min_lat)) * 100;\n    return `${x.toFixed(2)},${y.toFixed(2)}`;\n  }).join(\' \');\n\n  return (\n    <Card title="Observed Scene"\n          badge={<Badge tone={synthetic ? \'warning\' : \'accent\'}>{synthetic ? \'synthetic\' : \'real\'}</Badge>}\n          caption={`Outline from the ${slick?.detector ?? \'detector\'}. ${C.darkness}`}>\n      <div className="scene-wrap">\n        <img className="scene-img" src={sceneUrl} alt="Radar scene of the incident area" />\n        {pts && (\n          <svg className="scene-overlay" viewBox="0 0 100 100" preserveAspectRatio="none" role="img"\n               aria-label={`Detected slick outline covering ${g?.area_km2} square kilometres`}>\n            <polygon points={pts} className="scene-poly" />\n          </svg>\n        )}\n        {slick && !slick.detected && <div className="scene-nodetect">No slick detected</div>}\n      </div>\n\n      {g && (\n        <div style={{ marginTop: \'var(--space-5)\' }}>\n          <StatGrid cols={3}>\n            <Stat label="Area" value={`${g.area_km2.toFixed(2)} km²`} caption={C.area} />\n            <Stat label="Perimeter" value={`${g.perimeter_km.toFixed(2)} km`} caption={C.perimeter} />\n            <Stat label="Elongation" value={g.elongation.toFixed(2)} caption={C.elongation} />\n            <Stat label="Long axis" value={`${g.major_axis_km.toFixed(2)} km`} caption={C.majorAxis} />\n            <Stat label="Short axis" value={`${g.minor_axis_km.toFixed(2)} km`} caption={C.minorAxis} />\n            <Stat label="Bearing" value={`${g.orientation_deg_from_north.toFixed(1)}° from N`} caption={C.bearing} />\n            {slick.truth_agreement_iou != null && (\n              <Stat label="Agreement with truth mask" value={slick.truth_agreement_iou.toFixed(4)} caption={C.truthIou} />\n            )}\n            <Stat label="Pixel spacing" value={`${meta.pixel_spacing_m} m`} caption={C.pixelSpacing} />\n            <Stat label="Vessels tracked" value={nVessels} caption="Vessels with AIS tracks in this scene." />\n          </StatGrid>\n        </div>\n      )}\n\n      <p className="card-foot">\n        {meta.incident_id} · acquired {meta.acquired_utc.replace(\'T\', \' \').replace(\'+00:00\', \' UTC\')}.\n        {\' \'}{slick?.downstream_note} {slick?.measurement_note}\n      </p>\n    </Card>\n  );\n}\n', 'frontend/src/cards/HistoricalReplayCard.jsx': "import TimeSliderMap from '../TimeSliderMap';\n\n/**\n * Historical replay, chrome only: the card frame, badge and caption now come\n * from the shared Card (inside TimeSliderMap); the map itself is unchanged\n * until Phase 4.\n */\nexport default function HistoricalReplayCard({ incidentId, api, tracks, topCandidateId }) {\n  return (\n    <TimeSliderMap incidentId={incidentId} api={api} tracksData={tracks}\n                   topCandidateId={topCandidateId} />\n  );\n}\n", 'frontend/src/cards/AskSlickTraceCard.jsx': 'import AskConsole from \'../AskConsole\';\nimport { Badge, Card } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * Ask Slick Trace, shell only: the shared Card around the existing console.\n * The console\'s content is unchanged until Phase 6.\n */\nexport default function AskSlickTraceCard({ incidentId, api }) {\n  return (\n    <Card title="Ask Slick Trace" badge={<Badge>rule-based intent matching</Badge>}\n          caption={C.ask} className="console-panel">\n      <AskConsole incidentId={incidentId} api={api} />\n    </Card>\n  );\n}\n', 'frontend/src/cards/FragilityCard.jsx': 'import { useMemo, useState } from \'react\';\nimport { Badge, Card, EmptyState, Stat, StatGrid } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * Rank fragility: what would have to change for the leader to change.\n *\n * Every value is a precomputed run on the server\'s grid. Choosing a setting\n * selects a computed point; nothing is interpolated for a setting that was\n * not run. On an abstained case the leader was never named, and says so.\n */\nconst AXIS_ORDER = [\'current_u_bias\', \'current_v_bias\', \'diffusivity_scale\', \'mask_threshold\', \'duration_shift_h\'];\n\nexport default function FragilityCard({ fragility }) {\n  const [axis, setAxis] = useState(\'current_u_bias\');\n  const [pointId, setPointId] = useState(null);\n\n  const points = useMemo(() => (fragility?.grid ?? [])\n    .filter((g) => Object.keys(g.changed_axes).length === 1 && axis in g.changed_axes)\n    .sort((a, b) => a.changed_axes[axis] - b.changed_axes[axis]), [fragility, axis]);\n\n  if (!fragility) return null;\n  if (!fragility.testable) {\n    return (\n      <Card title="Rank Fragility" badge={<Badge tone="warning">not testable</Badge>}>\n        <EmptyState>Not testable for this incident: {fragility.reason}</EmptyState>\n      </Card>\n    );\n  }\n  const unnamed = fragility.baseline_unknown_source;\n  const flip = fragility.smallest_flip;\n  const selected = pointId ? fragility.grid.find((g) => g.point_id === pointId) : null;\n  const label = (k) => fragility.axes[k]?.label ?? k;\n\n  return (\n    <Card title="Rank Fragility"\n          badge={<Badge tone={fragility.flip_found ? \'warning\' : \'accent\'}>\n            {fragility.flip_found ? \'lead can flip\' : \'lead held\'}</Badge>}\n          caption="What would have to change in the assumptions for a different vessel to lead."\n          footnote={`${fragility.interpretation_note} ${fragility.coverage_note}`}>\n      <StatGrid cols={2}>\n        <Stat label={unnamed ? \'Unnamed leader (no source was named)\' : \'Leader\'} mono\n              value={fragility.baseline_top} caption="The vessel with the best fit before any change." />\n        <Stat label="Lead held"\n              value={`${Math.round(fragility.lead_retained_fraction * 100)}% of ${fragility.n_points_tested}`}\n              caption={C.leadHeld} />\n      </StatGrid>\n\n      {flip ? (\n        <div className="flip-box">\n          <StatGrid cols={2}>\n            <Stat label="Smallest change that flips the lead"\n                  value={Object.entries(flip.changed_axes).map(([k, v]) => `${label(k)} ${v}`).join(\', \')}\n                  caption={`Magnitude ${flip.magnitude}. ${C.magnitude}`} />\n            <Stat label="Leader under that change" mono value={flip.top_candidate}\n                  caption={`IoU ${flip.top_iou.toFixed(3)}; ${fragility.baseline_top} is now at IoU ${flip.baseline_candidate_iou.toFixed(3)}. `\n                    + (flip.top_iou < flip.baseline_candidate_iou ? C.lossRanking : C.meanIou)} />\n          </StatGrid>\n        </div>\n      ) : (\n        <p className="card-caption" style={{ marginTop: \'var(--space-4)\' }}>\n          No tested perturbation changed the leader.\n        </p>\n      )}\n\n      <div style={{ marginTop: \'var(--space-5)\' }}>\n        <div className="ui-row">\n          <label className="stat-label" htmlFor="frag-axis">Try one setting</label>\n          <select id="frag-axis" className="ui-select" value={axis}\n                  onChange={(e) => { setAxis(e.target.value); setPointId(null); }}>\n            {AXIS_ORDER.filter((a) => fragility.axes[a]).map((a) => (\n              <option key={a} value={a}>{label(a)}</option>\n            ))}\n          </select>\n        </div>\n        <p className="stat-caption">{C.sweep} Outlined values change the leader.</p>\n        <div className="chip-steps" role="group" aria-label={`Tested values for ${label(axis)}`}\n             style={{ marginTop: \'var(--space-2)\' }}>\n          {points.map((p) => (\n            <button key={p.point_id} type="button"\n                    className={`chip${pointId === p.point_id ? \' is-active\' : \'\'}${p.flipped ? \' is-flag\' : \'\'}`}\n                    aria-pressed={pointId === p.point_id}\n                    onClick={() => setPointId(pointId === p.point_id ? null : p.point_id)}>\n              {String(p.changed_axes[axis])}\n              <span className="visually-hidden">{p.flipped ? \' changes the leader\' : \' leader unchanged\'}</span>\n            </button>\n          ))}\n        </div>\n        {selected && (\n          <div style={{ marginTop: \'var(--space-4)\' }}>\n            <StatGrid cols={3}>\n              <Stat label="Leader under this setting" mono value={selected.top_candidate}\n                    caption={selected.flipped ? \'A different vessel leads.\' : \'Same leader as before.\'} />\n              <Stat label="Leader IoU" value={selected.top_iou.toFixed(3)} caption={C.meanIou} />\n              <Stat label="Margin over next vessel" value={selected.loss_margin ?? \'—\'} caption={C.lossMargin} />\n            </StatGrid>\n          </div>\n        )}\n      </div>\n    </Card>\n  );\n}\n', 'frontend/src/cards/CoverageCard.jsx': 'import { Badge, Card, CaptionList } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * Coverage-aware matching: how radar contacts and AIS records are paired when\n * some AIS is hidden. An unmatched contact is an unresolved identity, never\n * automatically a suspect. A null rate had nothing to count and says so.\n */\nconst ROWS = [\n  [\'hidden_ais_recovery_rate\', \'hidden_ais_recovery_n\', \'Hidden-AIS recovery\'],\n  [\'false_unmatched_alert_rate\', \'false_unmatched_alert_n\', \'False unmatched alert\'],\n  [\'mistaken_promotion_rate\', \'mistaken_promotion_n\', \'Mistaken promotion\'],\n];\n\nfunction Rate({ value, n }) {\n  return (\n    <>\n      {value == null ? <span className="muted">not measured</span> : `${(value * 100).toFixed(1)}%`}\n      <span className="sub">{n}</span>\n    </>\n  );\n}\n\nexport default function CoverageCard({ coverage }) {\n  if (!coverage) return null;\n  const { selective, coverage_failure: failure } = coverage.conditions;\n  const op = coverage.operating_point;\n  return (\n    <Card title="Coverage-Aware Matching" badge={<Badge tone="accent">tested</Badge>}\n          caption="How well radar contacts are matched to AIS records when some AIS is deliberately hidden, one vessel at a time or a whole area at once."\n          footnote={`Operating point: match gate ${op.gate_radius_deg}°, detector miss rate ${op.detector_miss_rate}, hidden fraction ${op.hide_fraction_selective}, ${selective.n_runs} runs per condition.`}>\n      <table className="ui-table">\n        <caption className="visually-hidden">Matching rates under selective hiding and simulated coverage failure</caption>\n        <thead>\n          <tr><th scope="col">Rate</th><th scope="col">Vessels hidden</th><th scope="col">Area goes dark</th></tr>\n        </thead>\n        <tbody>\n          {ROWS.map(([rk, nk, label]) => (\n            <tr key={rk}>\n              <th scope="row">{label}</th>\n              <td><Rate value={selective[rk]} n={selective[nk]} /></td>\n              <td><Rate value={failure[rk]} n={failure[nk]} /></td>\n            </tr>\n          ))}\n        </tbody>\n      </table>\n      <CaptionList items={[\n        [\'Hidden-AIS recovery\', C.hiddenRecovery],\n        [\'False unmatched alert\', C.falseAlert],\n        [\'Mistaken promotion\', C.mistakenPromotion],\n        [\'Match gate\', C.gateRadius],\n        [\'Not measured\', C.notMeasured],\n      ]} />\n      <details className="text-equivalent">\n        <summary>What these rates do and do not establish</summary>\n        <ul className="cov-limits">{coverage.limits.map((l) => <li key={l}>{l}</li>)}</ul>\n      </details>\n    </Card>\n  );\n}\n', 'frontend/src/cards/ForecastCard.jsx': 'import { Badge, Card, CaptionList } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * Forward exposure: where modelled surface particles go after the image.\n * Modelled exposure and arrival intervals, never predicted damage; the\n * forcing mode is shown verbatim so a retrospective field is not mistaken\n * for an operational forecast.\n */\nconst hhmm = (s) => s.replace(\'T\', \' \').replace(\':00+00:00\', \' UTC\');\n\nexport default function ForecastCard({ forecast }) {\n  if (!forecast) return null;\n  return (\n    <Card title="Forward Exposure" badge={<Badge tone="warning">modelled</Badge>}\n          caption={`Where the slick’s surface particles are modelled to drift after the image, across ${forecast.n_ensemble_variants} forcing settings.`}\n          footnote={`${forecast.forcing_mode}. ${forecast.interpretation_note}`}>\n      <table className="ui-table">\n        <caption className="visually-hidden">Modelled spread and exposure by hours after the image</caption>\n        <thead>\n          <tr>\n            <th scope="col">Horizon</th>\n            <th scope="col">Modelled spread</th>\n            <th scope="col">Shoreline</th>\n            <th scope="col">Sensitive areas</th>\n          </tr>\n        </thead>\n        <tbody>\n          {forecast.horizons.map((h) => (\n            <tr key={h.horizon_hours}>\n              <th scope="row">+{h.horizon_hours} h<span className="sub">{hhmm(h.valid_utc)}</span></th>\n              <td>{h.envelope_area_km2.toFixed(1)} km²</td>\n              <td>{h.modelled_shoreline_fraction == null\n                ? <span className="muted">not modelled</span>\n                : `${(h.modelled_shoreline_fraction * 100).toFixed(1)}%`}</td>\n              <td>\n                <ul className="ui-list">\n                  {h.sensitive_area_exposure.map((a) => (\n                    <li key={a.name} className={a.any_contact ? \'\' : \'muted\'}>\n                      {a.name}{\' — \'}\n                      {a.any_contact ? `${(a.modelled_particle_fraction * 100).toFixed(1)}%` : \'no modelled contact\'}\n                    </li>\n                  ))}\n                </ul>\n              </td>\n            </tr>\n          ))}\n        </tbody>\n      </table>\n      <CaptionList items={[\n        [\'Horizon\', C.horizon],\n        [\'Modelled spread\', C.envelopeArea],\n        [\'Shoreline\', C.shoreline],\n        [\'Sensitive areas\', C.exposure],\n      ]} />\n    </Card>\n  );\n}\n', 'frontend/src/cards/ProvenanceCard.jsx': 'import { Badge, Card, Stat, StatGrid } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * Traffic filtering and run provenance: how many vessels the traced-back\n * origin area removed, in three honestly separate states, and what\n * identifies this run. Counts come from the report artifact; the run fields\n * from the Case contract\'s meta.\n */\nconst STATES = [[\'candidate\', \'Candidates\'], [\'excluded\', \'Excluded\'], [\'unassessed\', \'Unassessed\']];\n\nexport default function ProvenanceCard({ meta, report }) {\n  if (!meta) return null;\n  const counts = report?.historical_filtering?.status_counts;\n  const nFiles = report ? Object.keys(report.checksums_sha256 ?? {}).length : null;\n  return (\n    <Card title="Traffic Filtering and Provenance"\n          badge={<Badge>{meta.provenance.status} data</Badge>}\n          caption="Which vessels the traced-back origin area kept, and what identifies this run."\n          footnote={report?.not_a}>\n      <StatGrid cols={3}>\n        {STATES.map(([k, label]) => (\n          <Stat key={k} label={label} value={counts ? (counts[k] ?? 0) : \'—\'} caption={C[k]} />\n        ))}\n      </StatGrid>\n      <div style={{ marginTop: \'var(--space-5)\' }}>\n        <StatGrid cols={3}>\n          <Stat text label="AIS source" value={meta.ais_source} caption="Where the vessel tracks come from." />\n          <Stat text label="Forcing" value={meta.forcing_product} caption="The current field the drift model uses." />\n          <Stat label="Metric CRS" value={meta.metric_crs} mono caption="Map projection used for distances and areas." />\n          <Stat label="Seed" value={meta.generator.seed} mono caption={C.seed} />\n          <Stat label="Files hashed" value={nFiles == null ? \'—\' : `${nFiles} · SHA-256`} caption={C.checksums} />\n          <Stat text label="Licence" value={meta.data_licence} caption="Terms the data is released under." />\n        </StatGrid>\n      </div>\n    </Card>\n  );\n}\n', 'frontend/src/cards/NextObservationCard.jsx': 'import { Badge, Card, EmptyState, Stat, StatGrid } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * Next observation: which future image would best separate the two leading\n * explanations. Reads the artifact\'s own recommended_window rather than\n * re-deriving it. Recommends evidence; it does not task a satellite.\n */\nconst hhmm = (s) => s.replace(\'T\', \' \').replace(\':00+00:00\', \' UTC\');\n\nexport default function NextObservationCard({ nextObs }) {\n  if (!nextObs) return null;\n  if (!nextObs.applicable) {\n    return (\n      <Card title="Next Observation" badge={<Badge>not applicable</Badge>}>\n        <EmptyState>Not applicable for this incident: {nextObs.reason}</EmptyState>\n      </Card>\n    );\n  }\n  const rec = nextObs.recommended_window;\n  return (\n    <Card title="Next Observation" badge={<Badge tone="warning">advisory</Badge>}\n          caption={`When one more image would best tell ${nextObs.hypothesis_a.vessel_key} and ${nextObs.hypothesis_b.vessel_key} apart.`}\n          footnote={`${rec.schedule_status}. ${nextObs.scope_note} ${nextObs.method_note}`}>\n      <StatGrid cols={3}>\n        <Stat label="Recommended window" value={`+${rec.horizon_hours} h`}\n              caption={`${hhmm(rec.valid_utc)}. ${C.recommended}`} />\n        <Stat label="Disagreement then" value={`${Math.round(rec.disagreement_score * 100)}%`}\n              caption={C.disagreement} />\n        <Stat label="Predicted overlap then" value={rec.predicted_overlap_iou.toFixed(3)}\n              caption={C.overlapIou} />\n      </StatGrid>\n      <div style={{ marginTop: \'var(--space-5)\' }}>\n        <div className="stat-label">Every tested window</div>\n        <div className="chip-steps" role="list" style={{ marginTop: \'var(--space-2)\' }}>\n          {nextObs.windows.map((w) => (\n            <span key={w.horizon_hours} role="listitem"\n                  className={`chip${w.horizon_hours === rec.horizon_hours ? \' is-active\' : \'\'}`}>\n              +{w.horizon_hours} h · {Math.round(w.disagreement_score * 100)}%\n              <span className="visually-hidden">{w.horizon_hours === rec.horizon_hours ? \' recommended\' : \'\'}</span>\n            </span>\n          ))}\n        </div>\n        <p className="stat-caption">Hours after the image, with the disagreement at each; the recommended one is filled.</p>\n      </div>\n    </Card>\n  );\n}\n'}
APP_AFTER = 'import { useEffect, useState } from \'react\';\nimport \'./dashboard.css\';\nimport \'./shell.css\';\nimport { api } from \'./api\';\nimport { useCase } from \'./useCase\';\nimport CaseSwitcher from \'./CaseSwitcher\';\nimport ThemeToggle from \'./ThemeToggle\';\nimport ConclusionGraph from \'./ConclusionGraph\';\nimport CaseFindingCard from \'./cards/CaseFindingCard\';\nimport CandidateRankingCard from \'./cards/CandidateRankingCard\';\nimport ObservedSceneCard from \'./cards/ObservedSceneCard\';\nimport HistoricalReplayCard from \'./cards/HistoricalReplayCard\';\nimport FragilityCard from \'./cards/FragilityCard\';\nimport ForecastCard from \'./cards/ForecastCard\';\nimport NextObservationCard from \'./cards/NextObservationCard\';\nimport CoverageCard from \'./cards/CoverageCard\';\nimport ProvenanceCard from \'./cards/ProvenanceCard\';\nimport AskSlickTraceCard from \'./cards/AskSlickTraceCard\';\n\nexport default function App() {\n  const [incidents, setIncidents] = useState([]);\n  const [incidentId, setIncidentId] = useState(\'case_0001\');\n  const { case: c, report, tracks, error } = useCase(incidentId);\n\n  useEffect(() => {\n    api.listIncidents().then(setIncidents).catch(() => setIncidents([]));\n  }, []);\n\n  const meta = c?.meta;\n\n  return (\n    <div className="app-shell">\n      <header className="topbar">\n        <div className="wordmark">\n          <svg className="wordmark-mark" viewBox="0 0 18 18" aria-hidden="true">\n            <rect width="18" height="18" rx="5" fill="var(--accent)" />\n            <path d="M9 3.6s-3.1 3.9-3.1 5.9a3.1 3.1 0 0 0 6.2 0C12.1 7.5 9 3.6 9 3.6Z" fill="#fff" />\n            <path d="M3.8 14c1.2-.9 2.3-.9 3.5 0s2.3.9 3.5 0 2.3-.9 3.4 0" stroke="#fff"\n                  strokeWidth="1.2" fill="none" strokeLinecap="round" opacity=".85" />\n          </svg>\n          Slick Trace<span className="wordmark-sub">Source attribution</span>\n        </div>\n        <div className="topbar-trailing">\n          {meta && (\n            <div className="topbar-meta">\n              <span className="tag tag-teal">{meta.case_state.replace(\'_\', \' \')}</span>\n              {meta.provenance.status === \'synthetic\' && <span className="tag tag-amber">synthetic case</span>}\n            </div>\n          )}\n          <ThemeToggle />\n        </div>\n      </header>\n\n      {error && <div className="error-banner">Failed to load incident data: {error}</div>}\n\n      <div className="finder-layout">\n        <aside className="finder-sidebar">\n          <CaseSwitcher incidents={incidents} active={incidentId} onSelect={setIncidentId} />\n        </aside>\n\n        <div className="finder-content">\n          {/* Evidence column, in the order a reviewer needs it: finding first. */}\n          <div className="finder-features" key={incidentId}>\n            {c && (\n              <>\n                <CaseFindingCard attribution={c.attribution} baseline={c.baseline} vessels={c.vessels} />\n                <CandidateRankingCard kind="replay" attribution={c.attribution} baseline={c.baseline} />\n                <CandidateRankingCard kind="baseline" attribution={c.attribution} baseline={c.baseline} />\n                <ObservedSceneCard meta={meta} slick={c.slick} sceneUrl={api.sceneUrl(incidentId)}\n                                   nVessels={c.vessels.length} />\n                <HistoricalReplayCard incidentId={incidentId} api={api} tracks={tracks}\n                                      topCandidateId={c.attribution?.top_candidate_id} />\n                <FragilityCard fragility={c.fragility} />\n                <ForecastCard forecast={c.forecast} />\n                <NextObservationCard nextObs={c.next_observation} />\n                <CoverageCard coverage={c.coverage} />\n                <ProvenanceCard meta={meta} report={report} />\n              </>\n            )}\n          </div>\n\n          <div className="finder-details">\n            {meta && (\n              <div className="report-buttons">\n                <a className="report-button" href={api.reportUrl(incidentId)} target="_blank" rel="noreferrer">\n                  Investigation Report\n                </a>\n                <a className="report-button" href={api.dossierUrl(incidentId)} target="_blank" rel="noreferrer">\n                  Dossier (PDF)\n                </a>\n              </div>\n            )}\n            <ConclusionGraph key={incidentId} attribution={c?.attribution} naive={c?.baseline}\n                             report={report} detection={c?.slick} fragility={c?.fragility} />\n            <AskSlickTraceCard key={`ask-${incidentId}`} incidentId={incidentId} api={api} />\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n}\n'
