DELETE = ['frontend/src/VerdictBand.jsx', 'frontend/src/RankingPanel.jsx', 'frontend/src/ScenePanel.jsx', 'frontend/src/FragilityPanel.jsx', 'frontend/src/CoveragePanel.jsx', 'frontend/src/ForecastPanel.jsx', 'frontend/src/ProvenancePanel.jsx', 'frontend/src/NextObservationPanel.jsx', 'frontend/src/Masonry.jsx', 'frontend/src/TrackMap.jsx']

writes, deletes, skipped = {}, [], 0
read = lambda p: open(p, encoding="utf-8").read()

for p, text in NEW.items():
    if os.path.exists(p):
        if read(p) == text:
            skipped += 1; continue
        abort(f"{p} already exists with different content")
    writes[p] = text

app = read("frontend/src/App.jsx")
if app == APP_AFTER:
    skipped += 1
elif hashlib.sha256(app.encode("utf-8")).hexdigest() == APP_BEFORE_SHA:
    writes["frontend/src/App.jsx"] = APP_AFTER
else:
    abort("frontend/src/App.jsx is not the expected version (commit the conclusion graph first)")

staged = {}
for p, old, new in EDITS:
    t = staged.get(p) or read(p)
    if (old in new and new in t) or (old not in new and old not in t and new in t):
        skipped += 1; continue
    if t.count(old) != 1:
        abort(f"{p}: anchor {old.strip().splitlines()[0][:60]!r} matched {t.count(old)} times")
    staged[p] = t.replace(old, new, 1)
writes.update(staged)

for p in DELETE:
    if os.path.exists(p):
        deletes.append(p)
    else:
        skipped += 1

# nothing left behind may still import a deleted panel
gone = [os.path.basename(p)[:-4] for p in DELETE]
for root, _, files in os.walk("frontend/src"):
    for f in files:
        p = os.path.join(root, f)
        if p in deletes or not f.endswith((".jsx", ".js")):
            continue
        body = writes.get(p) or read(p)
        for g in gone:
            if f"/{g}'" in body:
                abort(f"{p} still imports {g}")

# create every directory before writing any file, so a path problem cannot
# leave the tree half-patched
for d in sorted({os.path.dirname(p) for p in writes} - {""}):
    os.makedirs(d, exist_ok=True)
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
for p in deletes:
    os.remove(p)
print(f"patch 05: {len(writes)} files written, {len(deletes)} deleted, {skipped} already in place.")
